    private void navButtons(LinearLayout p,boolean first){addSpace(p,18);LinearLayout n=new LinearLayout(this);n.setOrientation(LinearLayout.HORIZONTAL);Button next=button(step==3?tx("Preview form","معاينة الاستمارة","پێشبینینی فۆرم"):tx("Continue","متابعة","بەردەوام"),1);Button back=button(tx("Back","رجوع","گەڕانەوە"),0);n.addView(next,new LinearLayout.LayoutParams(0,dp(54),1));Space g=new Space(this);n.addView(g,new LinearLayout.LayoutParams(dp(8),1));n.addView(back,new LinearLayout.LayoutParams(0,dp(54),1));next.setOnClickListener(v->{captureStep();if(!validateStep())return;if(step<3){step++;showWizard();}else showPreview();});back.setOnClickListener(v->{captureStep();if(step>0){step--;showWizard();}else showHome();});p.addView(n);}

    private void captureStep(){if(step==0&&fClient!=null){draft.client=fClient.getText().toString().trim();draft.phone=fPhone.getText().toString().trim();draft.location=fLocation.getText().toString().trim();draft.date=fDate.getText().toString().trim();}else if(step==1&&fCapacity!=null){draft.capacity=fCapacity.getText().toString().trim();int s=fSystem.getSelectedItemPosition();draft.system=s==1?"On-Grid":s==2?"Off-Grid":"Hybrid";draft.phase=fPhase.getSelectedItemPosition()==1?"Three Phase":"Single Phase";}else if(step==3&&fOrganizer!=null){draft.organizer=fOrganizer.getText().toString().trim();draft.installation=fInstall.isChecked();draft.transport=fTransport.isChecked();draft.notes=buildNote();}}
    private boolean validateStep(){String err="";if(step==0){if(draft.client.isEmpty())err=tx("Client name is required","اسم العميل مطلوب","ناوی کڕیار پێویستە");else if(draft.phone.isEmpty())err=tx("Phone is required","رقم الهاتف مطلوب","تەلەفۆن پێویستە");else if(draft.location.isEmpty())err=tx("Location is required","الموقع مطلوب","شوێن پێویستە");}else if(step==1&&draft.capacity.isEmpty())err=tx("Capacity is required","السعة مطلوبة","توانا پێویستە");else if(step==2&&items.isEmpty())err=tx("Add at least one material","أضف مادة واحدة على الأقل","لانیکەم یەک ماددە زیاد بکە");else if(step==3&&draft.organizer.isEmpty())err=tx("Organizer is required","منظم الكشف مطلوب","ڕێکخەر پێویستە");if(!err.isEmpty()){Toast.makeText(this,err,Toast.LENGTH_LONG).show();return false;}return true;}

