    private void showCatalog(){clear("catalog");LinearLayout p=pageScroll();title(p,tx("Material catalog","كتالوج المواد","کاتەلۆگی ماددە"),catalog.size()+" "+tx("items","مادة","ماددە"));EditText search=field(tx("Search item name…","ابحث باسم المادة…","بە ناوی ماددە بگەڕێ…"),"");p.addView(search,new LinearLayout.LayoutParams(-1,dp(54)));addSpace(p,10);HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout chips=new LinearLayout(this);chips.setOrientation(LinearLayout.HORIZONTAL);hs.addView(chips);p.addView(hs,new LinearLayout.LayoutParams(-1,dp(46)));LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);p.addView(list);String[] filters={"ALL","PANELS","INVERTER","BATTERY","STRUCTURE","ACCESSORY","INSTALL"};for(String f:filters){TextView ch=pill(catLabel(f),f.equals(catalogFilter)?TEAL:Color.WHITE,f.equals(catalogFilter)?Color.WHITE:NAVY);ch.setOnClickListener(v->{catalogFilter=f;showCatalog();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(36));lp.leftMargin=dp(3);lp.rightMargin=dp(3);chips.addView(ch,lp);}Runnable render=()->renderCatalogList(list,search.getText().toString().trim().toLowerCase(Locale.ROOT));search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){render.run();}public void afterTextChanged(Editable e){}});render.run();}
    private String catLabel(String f){if(f.equals("ALL"))return tx("All","الكل","هەموو");if(f.equals("PANELS"))return tx("Panels","ألواح","پانێڵ");if(f.equals("INVERTER"))return tx("Inverters","إنفرترات","ئینڤێرتەر");if(f.equals("BATTERY"))return tx("Batteries","بطاريات","باتری");if(f.equals("STRUCTURE"))return tx("Structures","هياكل","هەیکەل");if(f.equals("ACCESSORY"))return tx("Accessories","ملحقات","پێداویستی");return tx("Installation","تركيب/نقل","دامەزراندن");}
    private String catGroup(Product x){String c=(x.category+" "+x.name).toLowerCase(Locale.ROOT);if(c.contains("panel"))return"PANELS";if(c.contains("inverter"))return"INVERTER";if(c.contains("battery")||c.contains("bms"))return"BATTERY";if(c.contains("structure")||c.contains("rack"))return"STRUCTURE";if(c.contains("install")||c.contains("delivery")||c.contains("transport"))return"INSTALL";return"ACCESSORY";}
    private void renderCatalogList(LinearLayout list,String q){list.removeAllViews();for(Product x:catalog){if(!catalogFilter.equals("ALL")&&!catGroup(x).equals(catalogFilter))continue;if(!q.isEmpty()&&!x.name.toLowerCase(Locale.ROOT).contains(q))continue;LinearLayout c=card();LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);r.setGravity(Gravity.CENTER_VERTICAL);LinearLayout txt=new LinearLayout(this);txt.setOrientation(LinearLayout.VERTICAL);txt.addView(tv(x.name,14,true,NAVY));txt.addView(tv(x.category,10,false,MUTED));r.addView(txt,new LinearLayout.LayoutParams(0,-2,1));TextView add=pill("+",Color.rgb(232,250,246),TEAL_DARK);r.addView(add,new LinearLayout.LayoutParams(dp(40),dp(34)));c.addView(r);c.setOnClickListener(v->{LineItem it=new LineItem();it.name=x.name;it.category=x.category;items.add(it);Toast.makeText(this,tx("Added","تمت الإضافة","زیادکرا"),Toast.LENGTH_SHORT).show();});list.addView(c);addSpace(list,8);}}

    private void showItemPicker(final int replaceIndex){final Dialog d=new Dialog(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(14),dp(14),dp(14),dp(14));box.setBackgroundColor(Color.WHITE);EditText search=field(tx("Search item name…","ابحث باسم المادة…","بە ناوی ماددە بگەڕێ…"),"");box.addView(search,new LinearLayout.LayoutParams(-1,dp(54)));ListView lv=new ListView(this);box.addView(lv,new LinearLayout.LayoutParams(-1,0,1));final ArrayList<Product> result=new ArrayList<>();final ArrayList<String> names=new ArrayList<>();final ArrayAdapter<String> ad=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,names);lv.setAdapter(ad);Runnable r=()->{String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);result.clear();names.clear();for(Product x:catalog)if(q.isEmpty()||x.name.toLowerCase(Locale.ROOT).contains(q)){result.add(x);names.add(x.name);}ad.notifyDataSetChanged();};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){r.run();}public void afterTextChanged(Editable e){}});lv.setOnItemClickListener((a,v,pos,id)->{Product x=result.get(pos);if(replaceIndex>=0){LineItem old=items.get(replaceIndex);old.name=x.name;old.category=x.category;}else{LineItem it=new LineItem();it.name=x.name;it.category=x.category;items.add(it);}d.dismiss();showWizard();});r.run();d.setContentView(box);Window w=d.getWindow();if(w!=null){w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.92f),(int)(getResources().getDisplayMetrics().heightPixels*.82f));w.setBackgroundDrawableResource(android.R.color.transparent);}d.show();if(w!=null)w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.92f),(int)(getResources().getDisplayMetrics().heightPixels*.82f));}
    private void editItem(final int index,LineItem existing){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),dp(8),dp(18),0);EditText name=field(tx("Item name","اسم المادة","ناوی ماددە"),existing==null?"":existing.name);EditText qty=field(tx("Quantity","الكمية","بڕ"),existing==null?"1":existing.qty);EditText price=field(tx("Unit price (optional)","سعر الوحدة (اختياري)","نرخی یەکە (ئارەزوومەندانە)"),existing==null?"":existing.price);box.addView(name,new LinearLayout.LayoutParams(-1,dp(52)));addSpace(box,8);box.addView(qty,new LinearLayout.LayoutParams(-1,dp(52)));addSpace(box,8);box.addView(price,new LinearLayout.LayoutParams(-1,dp(52)));new AlertDialog.Builder(this).setTitle(existing==null?tx("Custom item","مادة مخصصة","ماددەی تایبەت"):tx("Edit item","تعديل المادة","دەستکاری ماددە")).setView(box).setPositiveButton(tx("Save","حفظ","پاشەکەوت"),(d,w)->{LineItem it=existing==null?new LineItem():existing;it.name=name.getText().toString().trim();it.qty=qty.getText().toString().trim().isEmpty()?"1":qty.getText().toString().trim();it.price=price.getText().toString().trim();if(existing==null)items.add(it);showWizard();}).setNegativeButton(tx("Cancel","إلغاء","هەڵوەشاندنەوە"),null).show();}

